// Pure helpers for AI provenance (IA-01). Content generated by AI carries the
// mark "AI · pending review" plus its provider until a person reviews it; the
// record is kept afterwards (reviewedBy/reviewedAt) for audit.

import type { AiDestination, AiProvenance, ProvenanceMap } from "./types";

export function newProvenance(destination: AiDestination, now = new Date()): AiProvenance {
  return { ...destination, generatedAt: now.toISOString() };
}

export function isPendingReview(p: AiProvenance | undefined): p is AiProvenance {
  return !!p && !p.reviewedAt;
}

/** True when any field of the map still waits for a human review. */
export function hasPendingReview(map: ProvenanceMap | undefined): boolean {
  return Object.values(map ?? {}).some(isPendingReview);
}

/** Records new AI content for a field (a new generation resets any review). */
export function withProvenance(
  map: ProvenanceMap | undefined,
  field: string,
  provenance: AiProvenance,
): ProvenanceMap {
  return { ...(map ?? {}), [field]: provenance };
}

/** Marks one field as reviewed by a person. */
export function markReviewed(
  map: ProvenanceMap | undefined,
  field: string,
  reviewedBy: string,
  now = new Date(),
): ProvenanceMap {
  const current = map?.[field];
  if (!current) return map ?? {};
  return { ...map, [field]: { ...current, reviewedBy, reviewedAt: now.toISOString() } };
}
